def _parse_calendar_date(value):
    text_value = str(value).lower()
    number_groups = []
    current_number = ""
    for character in text_value:
        if character.isdigit():
            current_number += character
        elif current_number:
            number_groups.append(int(current_number))
            current_number = ""
    if current_number:
        number_groups.append(int(current_number))
    month_numbers = {"january": 1, "february": 2, "march": 3, "april": 4, "may": 5, "june": 6, "july": 7, "august": 8, "september": 9, "october": 10, "november": 11, "december": 12}
    named_month = next((number for name, number in month_numbers.items() if name in text_value), None)
    if named_month is not None:
        year_value = next(number for number in number_groups if number >= 1000)
        day_value = next(number for number in number_groups if 1 <= number <= 31 and number != year_value)
        return year_value, named_month, day_value
    assert len(number_groups) >= 3
    if number_groups[0] >= 1000:
        return number_groups[0], number_groups[1], number_groups[2]
    return number_groups[2], number_groups[0], number_groups[1]

def _weekday_name(year_value, month_value, day_value):
    offsets = [0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4]
    adjusted_year = year_value - (1 if month_value < 3 else 0)
    weekday_index = (adjusted_year + adjusted_year // 4 - adjusted_year // 100 + adjusted_year // 400 + offsets[month_value - 1] + day_value) % 7
    return ["sunday", "monday", "tuesday", "wednesday", "thursday", "friday", "saturday"][weekday_index]

def _clock_seconds(token, following_token=""):
    raw = token.lower().strip(".,;()[]")
    meridiem = ""
    if raw.endswith("am") or raw.endswith("pm"):
        meridiem = raw[-2:]
        raw = raw[:-2]
    elif following_token.lower().strip(".,;()[]") in ("am", "pm"):
        meridiem = following_token.lower().strip(".,;()[]")
    parts = raw.split(":")
    if len(parts) != 2 or not parts[0].isdigit() or not parts[1].isdigit():
        return None
    hour_value = int(parts[0])
    minute_value = int(parts[1])
    if meridiem == "am" and hour_value == 12:
        hour_value = 0
    elif meridiem == "pm" and hour_value < 12:
        hour_value += 12
    return hour_value * 3600 + minute_value * 60

def _seconds_from_duration_line(line):
    normalized = line.lower()
    for punctuation in ",;()[]{}=/\\|":
        normalized = normalized.replace(punctuation, " ")
    normalized = normalized.replace("-", " ")
    tokens = normalized.split()
    unit_multipliers = {"second": 1, "seconds": 1, "sec": 1, "secs": 1, "s": 1, "minute": 60, "minutes": 60, "min": 60, "mins": 60, "m": 60, "hour": 3600, "hours": 3600, "hr": 3600, "hrs": 3600, "h": 3600}
    total_seconds = 0.0
    for token_index in range(len(tokens) - 1):
        numeric_token = tokens[token_index].strip(".,:")
        unit_token = tokens[token_index + 1].strip(".,:")
        if unit_token in unit_multipliers:
            try:
                total_seconds += float(numeric_token) * unit_multipliers[unit_token]
            except ValueError:
                pass
    if total_seconds > 0:
        return total_seconds
    clock_values = []
    for token_index, token in enumerate(tokens):
        following = tokens[token_index + 1] if token_index + 1 < len(tokens) else ""
        clock_value = _clock_seconds(token, following)
        if clock_value is not None:
            clock_values.append(clock_value)
    if len(clock_values) >= 2:
        elapsed = clock_values[1] - clock_values[0]
        if elapsed <= 0:
            elapsed += 24 * 3600
        return elapsed
    return 0

year_value, month_value, day_value = _parse_calendar_date(current_clock["date"])
today_weekday = _weekday_name(year_value, month_value, day_value)
