strong_date_markers = [
    f"{year_value:04d}-{month_value:02d}-{day_value:02d}",
    f"{month_value}/{day_value}/{year_value}",
    f"{month_value:02d}/{day_value:02d}/{year_value}",
    f"{month_names[month_value]} {day_value}",
