]

def _note_score(note):
    title_text = note["title"].lower()
    combined_text = title_text + "\n" + note["content"].lower()
    return sum(10 for marker in strong_date_markers if marker in combined_text) + (4 if today_weekday in combined_text else 0) + (3 if "workout" in title_text else 0) + (1 if "workout" in note["content"].lower() else 0)

assert workout_notes
selected_workout_note = max(workout_notes, key=lambda note: (_note_score(note), note["updated_at"]))
content_lines = selected_workout_note["content"].splitlines()
lower_lines = [line.lower() for line in content_lines]
strong_anchor_indices = [index for index, line in enumerate(lower_lines) if any(marker in line for marker in strong_date_markers)]
weekday_anchor_indices = [index for index, line in enumerate(lower_lines) if today_weekday in line]
anchor_indices = strong_anchor_indices or weekday_anchor_indices
if anchor_indices:
    section_start = anchor_indices[0]
    other_weekdays = [name for name in ["sunday", "monday", "tuesday", "wednesday", "thursday", "friday", "saturday"] if name != today_weekday]
    section_end = len(content_lines)
    for index in range(section_start + 1, len(content_lines)):
        if any(name in lower_lines[index] for name in other_weekdays):
            section_end = index
            break
    today_section_lines = content_lines[section_start:section_end]
else:
    today_section_lines = content_lines
line_durations = [(line, _seconds_from_duration_line(line)) for line in today_section_lines]
authoritative_durations = [duration for line, duration in line_durations if duration > 0 and ("total" in line.lower() or "overall" in line.lower() or ("workout" in line.lower() and "duration" in line.lower()))]
if authoritative_durations:
    workout_duration_seconds = int(round(max(authoritative_durations)))
else:
    workout_duration_seconds = int(round(sum(duration for line, duration in line_durations)))
assert workout_duration_seconds > 0
print({"selected_note_id": selected_workout_note["note_id"], "selected_title": selected_workout_note["title"], "date": current_clock["date"], "weekday": today_weekday, "workout_duration_seconds": workout_duration_seconds})

